  ```typescript
  // src/ticket.ts
  import { OllamaService, Ticket } from './services/ticket.service';

  export async function sortTicketsByPriorit(ollamaService: OllamaService): Promise<void> {
    console.log('Starting ticket sort');
    const tickets = await ollamaService.getAllTickets();
    const maxTickets = Math.max(...tickets.map((ticket) => ticket.quantity));

    const ticketsToSort = tickets.filter((ticket) => ticket.quantity < maxTickets);
    await sortTickets(ticketsToSort, ollamaService);
  }

  async function sortTickets(tickets: Ticket[], ollamaService: OllamaService): Promise<void> {
    console.log('Starting ticket sort');
    tickets.sort((a, b) => a.priority - b.priority);

    const ticketsToSort: Ticket[] = [];
    const maxTickets = Math.max(...tickets.map((ticket) => ticket.quantity));

    const ticketsToSortByPriority = tickets.filter((ticket) => ticket.priority >= maxTickets);

    ticketsToSort.sort((a, b) => a.priority - b.priority);
    ticketsToSortByPriority.forEach(ticket => {
      ollamaService.assignTicket(ticket, ollamaService);
      tickets.push(ticket);
    });

    ollamaService.setTicketCount(tickets, ollamaService);
  }
  ```

