### sortTicketsByPriority

```typescript
export function sortTicketsByPriority(tickets: Tickets[]): Tickets[] {
  return tickets.sort((a, b) => {
    if (a.priority === b.priority) {
      return 0;
    } else if (a.priority < b.priority) {
      return -1;
    } else {
      return 1;
    }
  });
}
```

