```typescript
export interface Ticket {
    id: number;
    title: string;
    priority: number;
    status: Status;
    description: string;
}

export interface Status {
    name: string;
    value: number;
}

export function sortTickets(tickets: Ticket[]): Ticket[] {
    return tickets.sort((ticket1, ticket2) => {
        if (ticket1.priority < ticket2.priority) {
            return -1;
        }
        if (ticket1.priority > ticket2.priority) {
            return 1;
        }
        if (ticket1.status.value < ticket2.status.value) {
            return -1;
        }
        if (ticket1.status.value > ticket2.status.value) {
            return 1;
        }
        return 0;
    });
}
```

